const reviewText = $input.first().json['Review Text'];
const reviewId = $input.first().json['Review ID'];

let sentiment = 'Neutral';
const positiveKeywords = ['great', 'excellent', 'amazing', 'happy', 'love', 'satisfied', 'good', 'fantastic', 'awesome', 'recommend'];
const negativeKeywords = ['bad', 'poor', 'disappointed', 'problem', 'unhappy', 'frustrating', 'issue', 'terrible', 'worst'];

const lowerCaseReview = reviewText.toLowerCase();

let positiveCount = 0;
positiveKeywords.forEach(keyword => {
    if (lowerCaseReview.includes(keyword)) {
        positiveCount++;
    }
});

let negativeCount = 0;
negativeKeywords.forEach(keyword => {
    if (lowerCaseReview.includes(keyword)) {
        negativeCount++;
    }
});

if (positiveCount > negativeCount) {
    sentiment = 'Positive';
} else if (negativeCount > positiveCount) {
    sentiment = 'Negative';
} else if (positiveCount > 0 && negativeCount > 0) {
    sentiment = 'Mixed'; // For cases with both positive and negative keywords
}

return [{ json: { sentiment: sentiment, reviewId: reviewId } }];
